import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it first fills up.

    Create a queue.Queue of integers with maximum size `cap`, then try to
    put each element of `xs` in order without blocking (put_nowait). Stop
    at the first queue.Full and return the number of puts accepted so far.
    Nothing is ever taken from the queue.

    A capacity of zero or less accepts nothing, so the result is 0. This
    is a deliberate departure from queue.Queue, where maxsize <= 0 means
    unbounded.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_capacity_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_capacity_one() -> None:
    assert accepted(1, [4, 5, 6]) == 1


def test_zero_capacity_accepts_nothing() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity_accepts_nothing() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_duplicates_are_counted() -> None:
    assert accepted(4, [5, 5, 5, 5, 5, 5]) == 4


def test_zero_capacity_empty_input() -> None:
    assert accepted(0, []) == 0

